(function () {
  "use strict";

  var form = document.getElementById("waitlist-form");
  if (!form) return;

  // Shared across EN and /pt/ pages — the form itself is fully translated
  // in the PT pages' own HTML, but these status messages are generated by
  // this script at runtime, so they need their own language switch (keyed
  // off <html lang>, same signal the browser/SEO tags already use) rather
  // than showing English text on an otherwise Portuguese page.
  var isPt = document.documentElement.lang === "pt";
  var MESSAGES = {
    enterName: isPt ? "Por favor insere o teu nome." : "Please enter your name.",
    enterEmail: isPt ? "Por favor insere um email válido." : "Please enter a valid email address.",
    joining: isPt ? "A juntar…" : "Joining…",
    rateLimited: isPt
      ? "Demasiadas tentativas — tenta novamente daqui a um minuto."
      : "Too many attempts — please try again in a minute.",
    genericError: isPt
      ? "Algo correu mal. Tenta novamente daqui a instantes."
      : "Something went wrong. Please try again in a moment.",
  };

  var list = form.getAttribute("data-list");
  var submitBtn = form.querySelector("button[type=submit]");
  var messageEl = document.getElementById("waitlist-message");
  var confirmedUrl = form.getAttribute("data-confirmed-url");
  var submitLabel = submitBtn.textContent;

  function showMessage(text, isError) {
    messageEl.textContent = text;
    messageEl.classList.remove("is-error", "is-success");
    messageEl.classList.add("is-visible", isError ? "is-error" : "is-success");
  }

  function isValidEmail(value) {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
  }

  form.addEventListener("submit", function (event) {
    event.preventDefault();

    var hasNameField = !!form.elements["name"];
    var name = hasNameField ? form.elements["name"].value.trim() : "";
    var email = form.elements["email"].value.trim();
    var company = form.elements["company"] ? form.elements["company"].value : "";

    if (hasNameField && name.length < 2) {
      showMessage(MESSAGES.enterName, true);
      return;
    }
    if (!isValidEmail(email)) {
      showMessage(MESSAGES.enterEmail, true);
      return;
    }

    submitBtn.disabled = true;
    submitBtn.textContent = MESSAGES.joining;

    var payload = { email: email, list: list, company: company };
    if (name) payload.name = name;

    fetch("/api/waitlist", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    })
      .then(function (response) {
        return response.json().then(function (data) {
          return { ok: response.ok, status: response.status, data: data };
        });
      })
      .then(function (result) {
        if (result.ok) {
          window.location.href = confirmedUrl;
          return;
        }
        if (result.status === 429) {
          showMessage(MESSAGES.rateLimited, true);
        } else {
          showMessage(MESSAGES.genericError, true);
        }
        submitBtn.disabled = false;
        submitBtn.textContent = submitLabel;
      })
      .catch(function () {
        showMessage(MESSAGES.genericError, true);
        submitBtn.disabled = false;
        submitBtn.textContent = submitLabel;
      });
  });
})();
